"""
i18n.py  -  all the words the app shows, in 6 languages.

Languages: English (en), Tamil (ta), Hindi (hi), Kannada (kn), Malayalam (ml), Telugu (te).

IMPORTANT: the translations are a first draft. Please ask native speakers to read them
(especially the legal words) before the app is used with real workers.
"""

LANGS = {
    "English": "en",
    "தமிழ்": "ta",
    "हिन्दी": "hi",
    "ಕನ್ನಡ": "kn",
    "മലയാളം": "ml",
    "తెలుగు": "te",
}
ORDER = ["en", "ta", "hi", "kn", "ml", "te"]
LANG_NAME_EN = {"en": "English", "ta": "Tamil", "hi": "Hindi", "kn": "Kannada", "ml": "Malayalam", "te": "Telugu"}

STRINGS = {}


def s(key, en, ta, hi, kn, ml, te):
    STRINGS[key] = dict(zip(ORDER, (en, ta, hi, kn, ml, te)))


def t(lang, key, **kw):
    """Get the text for a key in a language (falls back to English)."""
    entry = STRINGS.get(key, {})
    text = entry.get(lang) or entry.get("en") or key
    return text.format(**kw) if kw else text


